<?php
declare(strict_types=1);
require __DIR__.'/../tools/marketplace/server/Market.php';
function check(bool $v):void {if(!$v)throw new RuntimeException('Test assertion failed.');}
function refuses(callable $fn,int $status):void {try{$fn();}catch(MarketError $e){check($e->status===$status);return;}throw new RuntimeException('Unexpectedly accepted operation.');}
$m=new Market(new PDO('sqlite::memory:'));$m->migrate();$m->migrate();
$a=$m->user('Seller');$b=$m->user('Buyer');$c=$m->user('Unrelated player');$op=$m->user('Operator','admin');
$seller=$m->auth($a['token']);$buyer=$m->auth($b['token']);$other=$m->auth($c['token']);$admin=$m->auth($op['token']);
refuses(fn()=>$m->auth(str_repeat('0',64)),401);
$gold=[['code'=>'gld','label'=>'Gold','quality'=>2,'index'=>-1,'quantity'=>1000,'ethereal'=>-1,'kind'=>'gold']];
$item=['seed'=>4294967295,'code'=>'rin','quality'=>7,'index'=>42,'ethereal'=>0,'sockets'=>0,'item_hex'=>'abcd'];
$listing=$m->listing($admin,['owner'=>$seller['id'],'item'=>$item,'price'=>$gold],false);
refuses(fn()=>$m->listing($buyer,['owner'=>$buyer['id'],'item'=>$item,'price'=>$gold],false),403);
$offer=['id'=>Market::id(),'type'=>'propose','listing_id'=>$listing['listing_id'],'listing_revision'=>1,'price'=>$gold,'message'=>'Would you take this?'];
$result=$m->command($buyer,$offer,false);check($result===$m->command($buyer,$offer,false));
check(count($m->snapshot($buyer,false)['offers'])===1&&count($m->snapshot($other,false)['offers'])===0);
refuses(fn()=>$m->command($buyer,array_replace($offer,['message'=>'Changed']),false),409);
refuses(fn()=>$m->command($seller,array_replace($offer,['id'=>Market::id()]),false),422);
$accept=['id'=>Market::id(),'type'=>'accept','offer_id'=>$offer['id'],'expected_revision'=>1];
refuses(fn()=>$m->command($buyer,$accept,false),403);refuses(fn()=>$m->command($other,$accept,false),403);
refuses(fn()=>$m->command($seller,$accept,true),404);
$replyGold=$gold;$replyGold[0]['quantity']=1500;
$counter=['id'=>Market::id(),'type'=>'counter','offer_id'=>$offer['id'],'expected_revision'=>1,'price'=>$replyGold,'message'=>'How about 1500?'];
$m->command($seller,$counter,false);
refuses(fn()=>$m->command($buyer,$accept,false),409);
$m->command($buyer,['id'=>Market::id(),'type'=>'message','offer_id'=>$offer['id'],'expected_revision'=>2,'message'=>'Agreed, thanks.'],false);
$m->command($buyer,array_replace($accept,['id'=>Market::id(),'expected_revision'=>3]),false);
$snapshot=$m->snapshot($seller,false);check($snapshot['offers'][0]['status']==='accepted'&&$snapshot['history']===[]);
check(array_column($snapshot['offers'][0]['events'],'kind')===['proposed','counter','message','accept']);
check($m->run('SELECT owner FROM items WHERE id=?',[$listing['item_id']])->fetchColumn()===$seller['id']);
refuses(fn()=>$m->sale($buyer,['item_id'=>$listing['item_id'],'seller'=>$seller['id'],'buyer'=>$buyer['id'],'price'=>$replyGold,'receipt'=>'test-receipt'],false),403);
$sale=['item_id'=>$listing['item_id'],'seller'=>$seller['id'],'buyer'=>$buyer['id'],'price'=>$replyGold,'receipt'=>'test-receipt'];
check($m->sale($admin,$sale,false)['duplicate']===false);check($m->sale($admin,$sale,false)['duplicate']===true);
$history=$m->snapshot($seller,false)['history'];check(count($history)===1&&$history[0]['seed']===4294967295&&$history[0]['price'][0]['quantity']===1500);
check($m->snapshot($buyer,true)['history']===[]);
$relisted=$m->listing($admin,['owner'=>$buyer['id'],'item_id'=>$listing['item_id'],'price'=>$gold],false);
$m->sale($admin,['item_id'=>$listing['item_id'],'seller'=>$buyer['id'],'buyer'=>$other['id'],'price'=>$gold,'receipt'=>'resale-receipt'],false);
check(count($m->snapshot($seller,false)['history'])===2);check($m->run('SELECT COUNT(*) FROM items')->fetchColumn()===1);
$collision=$m->listing($admin,['owner'=>$seller['id'],'item'=>$item,'price'=>$gold],false);check($collision['item_id']!==$listing['item_id']);
refuses(fn()=>$m->sale($admin,array_replace($sale,['buyer'=>$other['id']]),false),409);
refuses(fn()=>Market::price([array_replace($gold[0],['quantity'=>1.5])]),422);
refuses(fn()=>Market::price([array_replace($gold[0],['kind'=>'item'])]),422);
$two=$m->listing($admin,['owner'=>$seller['id'],'item'=>$item,'price'=>$gold],false);
$p=fn($actor)=>$m->command($actor,['id'=>Market::id(),'type'=>'propose','listing_id'=>$two['listing_id'],'listing_revision'=>1,'price'=>$gold],false);
$o1=$p($buyer);$o2=$p($other);
$m->command($seller,['id'=>Market::id(),'type'=>'accept','offer_id'=>$o1['offer_id'],'expected_revision'=>1],false);
refuses(fn()=>$m->command($seller,['id'=>Market::id(),'type'=>'accept','offer_id'=>$o2['offer_id'],'expected_revision'=>1],false),409);
check($m->run('SELECT status FROM offers WHERE id=?',[$o2['offer_id']])->fetchColumn()==='superseded');
check(count($m->historyPage(false,['item_id'=>$listing['item_id']])['rows'])===2);
check($m->historyPage(true,['item_id'=>$listing['item_id']])['rows']===[]);
check(count($m->historyPage(false,['code'=>'rin','seed'=>4294967295])['rows'])===2);
check(count($m->historyPage(false,['code'=>'rin','similar'=>true,'quality'=>7,'item_index'=>42,'ethereal'=>0,'sockets'=>0])['rows'])===2);
check($m->historyPage(false,['code'=>'rin','similar'=>true,'quality'=>6,'item_index'=>42,'ethereal'=>0,'sockets'=>0])['rows']===[]);
for($i=0;$i<201;++$i)$m->run("INSERT INTO events (id,item,at,actor,kind,message,price,seller,buyer,receipt) VALUES (?,?,?,?,?,?,?,?,?,?)",[Market::id(),$listing['item_id'],time(),$admin['id'],'completed_sale','Pagination fixture',json_encode($gold),$seller['id'],$buyer['id'],'page-'.$i]);
$page=$m->historyPage(false,['item_id'=>$listing['item_id']]);check(count($page['rows'])===200&&!$page['complete']);
$tail=$m->historyPage(false,['item_id'=>$listing['item_id'],'before'=>$page['next_before']]);check(count($tail['rows'])===3&&$tail['complete']);
check(count(array_unique(array_column(array_merge($page['rows'],$tail['rows']),'id')))===203);
$three=$m->listing($admin,['owner'=>$seller['id'],'item'=>$item,'price'=>$gold],false);$bounded=$m->command($buyer,['id'=>Market::id(),'type'=>'propose','listing_id'=>$three['listing_id'],'listing_revision'=>1,'price'=>$gold],false);
for($i=0;$i<499;++$i)$m->run("INSERT INTO events (id,item,offer,at,actor,kind,message,price) VALUES (?,?,?,?,?,?,?,?)",[Market::id(),$three['item_id'],$bounded['offer_id'],time(),$buyer['id'],'message','Log fixture','[]']);
refuses(fn()=>$m->command($seller,['id'=>Market::id(),'type'=>'message','offer_id'=>$bounded['offer_id'],'expected_revision'=>1,'message'=>'Too many'],false),422);
$m->command($seller,['id'=>Market::id(),'type'=>'reject','offer_id'=>$bounded['offer_id'],'expected_revision'=>1],false);
check(count($m->run('SELECT id FROM events WHERE offer=?',[$bounded['offer_id']])->fetchAll())===501);
echo "PHP/PDO marketplace: authentication, private threads, exact counters/messages, stale revisions, idempotency, single acceptance, fulfilment-only sales, resale lineage, seed collisions and mode isolation passed.\n";
